import { MakeLogicType, actions, connect, kea, listeners, path } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'

import { taskChannelsMembersRetrieve } from 'products/tasks/frontend/generated/api'
import { TaskUserBasicInfoApi } from 'products/tasks/frontend/generated/api.schemas'

import { TodayPreviewPayload } from './todayPreviewCardHandle'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPreviewCardLogicValues {
    currentTeamId: number | null // teamLogic
    spaceMembers: Record<string, TaskUserBasicInfoApi[] | null>
    spaceMembersLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPreviewCardLogicActions {
    loadSpaceMembers: ({ spaceId }: { spaceId: string }) => {
        spaceId: string
    }
    loadSpaceMembersFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSpaceMembersSuccess: (
        spaceMembers: Record<string, TaskUserBasicInfoApi[] | null>,
        payload?: {
            spaceId: string
        }
    ) => {
        spaceMembers: Record<string, TaskUserBasicInfoApi[] | null>
        payload?: {
            spaceId: string
        }
    }
    previewOpened: (payload: TodayPreviewPayload) => {
        payload: TodayPreviewPayload
    }
}

export type todayPreviewCardLogicType = MakeLogicType<todayPreviewCardLogicValues, todayPreviewCardLogicActions>

export const todayPreviewCardLogic = kea<todayPreviewCardLogicType>([
    path(['layout', 'today', 'todayPreviewCardLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    actions({
        previewOpened: (payload: TodayPreviewPayload) => ({ payload }),
    }),
    loaders(({ values }) => ({
        // A missing key is not loaded yet. `null` means the list did not load.
        spaceMembers: [
            {} as Record<string, TaskUserBasicInfoApi[] | null>,
            {
                loadSpaceMembers: async ({ spaceId }: { spaceId: string }) => {
                    let members: TaskUserBasicInfoApi[] | null = null
                    try {
                        members = await taskChannelsMembersRetrieve(String(values.currentTeamId), spaceId)
                    } catch {
                        members = null
                    }
                    return { ...values.spaceMembers, [spaceId]: members }
                },
            },
        ],
    })),
    listeners(({ actions, values }) => ({
        previewOpened: ({ payload }) => {
            // pinned: analytics event name and property. Renaming them breaks dashboards.
            posthog.capture('today rail preview opened', { kind: payload.kind })
            // Only a private space has a member list. The endpoint returns an empty list for the others.
            if (
                payload.kind === 'space' &&
                payload.space.channel_type === 'private' &&
                !(payload.space.id in values.spaceMembers)
            ) {
                actions.loadSpaceMembers({ spaceId: payload.space.id })
            }
        },
    })),
])
